  const auto a21=psplit_selective_tmaA_root_future40_read_eight(A+(gr+mh)*p.lda+gk);
  const auto a22=psplit_selective_tmaA_root_future40_read_eight(A+(gr+mh)*p.lda+gk+kh);
  psplit_selective_tmaA_root_future40_store_eight(&sA(row,k,0),a11);
  psplit_selective_tmaA_root_future40_store_eight(&sA(row,k,1),a12);
